"""Generate the tool guide from live schemas plus reviewed behavior notes. No Google calls."""

import argparse
import json
import os
from pathlib import Path
import re
import shlex
import subprocess


ROOT = Path(__file__).resolve().parents[2]
NOTES = Path(__file__).with_name("tool-reference.json")
OUTPUT = ROOT / "docs" / "tools.md"


def invoke(binary, *args):
    # Discovery and example checks must never consume a developer's credentials.
    env = {key: value for key, value in os.environ.items()
           if not key.startswith(("GOOGLE_", "MCP_"))}
    env["RUST_LOG"] = "off"
    return subprocess.run(
        [str(binary), "--no-env-file", "--auth-mode", "api-key", *args],
        env=env, capture_output=True, text=True, timeout=30,
    )


def flag(name):
    return "--" + re.sub(r"[A-Z]", lambda match: "-" + match[0].lower(), name).replace("_", "-")


def fields(schema, prefix=""):
    for name, value in sorted(schema.get("properties", {}).items()):
        path = f"{prefix}.{name}" if prefix else name
        required = name in schema.get("required", [])
        yield path, value, ("Yes" if not prefix else "When parent is supplied") if required else "No"
        yield from fields(value, path)
        if value.get("items", {}).get("properties"):
            yield from fields(value["items"], path + "[]")


def shape(schema):
    kind = schema.get("type", "value")
    if kind == "array":
        kind += " of " + schema.get("items", {}).get("type", "values")
    parts = [kind]
    for low, high, unit in [("minimum", "maximum", ""), ("minItems", "maxItems", " items")]:
        if low in schema or high in schema:
            parts.append(f'{schema.get(low, "unbounded")}–{schema.get(high, "unbounded")}{unit}')
    if "minLength" in schema:
        parts.append(f'at least {schema["minLength"]} character(s)')
    if "minLength" in schema.get("items", {}):
        parts.append(f'each item at least {schema["items"]["minLength"]} character(s)')
    choices = schema.get("enum", schema.get("items", {}).get("enum"))
    if choices:
        parts.append("values: " + ", ".join(f"`{value}`" for value in choices))
    if "pattern" in schema:
        parts.append(f'pattern: `{schema["pattern"]}`')
    return "; ".join(parts)


def prose_links(value):
    """Keep primary-source URLs clickable in both rustdoc and the web manual."""
    if isinstance(value, str):
        def link(match):
            url = match[0].rstrip(".,;")
            return "<" + url + ">" + match[0][len(url):]
        return re.sub(r"(?<![<(`])https?://[^\s<>`]+", link, value)
    if isinstance(value, list):
        return [prose_links(item) for item in value]
    if isinstance(value, dict):
        return {key: item if key == "example" else prose_links(item) for key, item in value.items()}
    return value


def cell(value):
    return str(value).replace("|", "\\|").replace("\n", " ")


def render(tools, notes):
    notes = prose_links(notes)
    if {tool["name"] for tool in tools} != set(notes):
        raise SystemExit("Tool names and reference notes differ; document every added/removed tool")
    lines = [
        "# Tool reference", "",
        "<!-- Generated by .github/scripts/tool-reference.py; edit its reviewed JSON notes, then regenerate. -->", "",
        "This reference describes the shared MCP and CLI tool interface. Parameter names,",
        "types, required fields and schema limits come from the executable's tool catalog.",
        "Defaults, response descriptions and behavioral restrictions are reviewed against",
        "the implementation. Google can impose additional API, coverage and quota limits.", "",
        "## Calling conventions", "",
        "Examples under each tool are MCP **argument objects**. Pass that object to the",
        "host's matching tool. For raw MCP `tools/call`, put the tool name in `name` and",
        "the object in `arguments`. Hosts may prefix tool names. With the CLI, use",
        "`mcp-gmap-rs call TOOL --args JSON` or the equivalent command/flags shown below.", "",
        "Only top-level parameters have CLI flags. Supply nested objects and arrays as",
        "JSON. Bare boolean flags mean true; `--flag false` sets false. Unknown top-level properties",
        "are rejected. Native API body objects accept Google's documented fields, which Google validates. Inspect an installed version with `tools` or `schema TOOL` before",
        "assuming it supports this release's complete catalog.", "",
        "Language-aware calls use the configured Google language. API-key/OAuth selection is process",
        "configuration, never a tool parameter. Exact `latitude,longitude` strings used",
        "as route waypoints are preserved; names may require Geocoding and Places fallback.", "",
        "All calls can be billable and share configured attempt budgets, deadlines and",
        "retries. Composite and matrix results may contain per-item errors on an otherwise",
        "successful call. Inspect those fields. Preserve Google links, review/photo authors",
        "and AI-summary disclosures with returned content. Examples are illustrative, not",
        "promises of current results or geographic coverage.", "",
        "## Tools", "",
    ]
    lines.extend(f'- [`{tool["name"]}`](#{tool["name"]})' for tool in tools)
    lines.append("")
    for tool in tools:
        name = tool["name"]
        note = notes[name]
        parameters = list(fields(tool["inputSchema"]))
        paths = {path for path, _, _ in parameters}
        if paths != set(note["parameters"]):
            raise SystemExit(f"{name}: undocumented or stale parameter paths: {paths ^ set(note['parameters'])}")
        command = name.removeprefix("maps_").replace("_", "-")
        lines += [f"## {name}", "", tool["description"], "", note["purpose"], "",
                  f"**CLI command:** `{command}`. **Google access:** {note['authentication']}", "",
                  "### Parameters", "",
                  "| Parameter / CLI flag | Type and schema limits | Required | Default when omitted | Description |",
                  "| --- | --- | --- | --- | --- |"]
        for path, schema, required in parameters:
            detail = note["parameters"][path]
            if not detail.get("description") or not detail.get("default"):
                raise SystemExit(f"{name}.{path}: description and omission behavior must be documented")
            label = f"`{path}`"
            if "." not in path:
                label += f" / `{flag(path)}`"
            lines.append("| " + " | ".join(map(cell, [label, shape(schema), required, detail["default"], detail["description"]])) + " |")
        lines += ["", "### Behavior and restrictions", ""]
        lines.extend("- " + item for item in note["notes"])
        lines += ["", "### Result", "", note["result"], "", "### Example", "", "MCP arguments:", "", "```json",
                  json.dumps(note["example"], ensure_ascii=False, indent=2), "```", "", "Equivalent CLI call:", "", "```sh",
                  f"mcp-gmap-rs call {name} --args " + shlex.quote(json.dumps(note["example"], ensure_ascii=False, separators=(",", ":"))),
                  "```", ""]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--binary", type=Path, required=True)
    parser.add_argument("--check", action="store_true", help="Fail if the committed guide differs")
    parser.add_argument("--verify-examples", action="store_true", help="Exercise examples with no credentials or Google calls")
    args = parser.parse_args()
    binary = args.binary.resolve()
    result = invoke(binary, "tools")
    if result.returncode:
        raise SystemExit("Could not discover the executable's tools")
    tools = json.loads(result.stdout)
    notes = json.loads(NOTES.read_text())
    text = render(tools, notes)
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != text:
            raise SystemExit("docs/tools.md is stale; regenerate with tool-reference.py --binary PATH")
    else:
        OUTPUT.write_text(text)
    if args.verify_examples:
        for tool in tools:
            result = invoke(binary, "call", tool["name"], "--args", json.dumps(notes[tool["name"]]["example"]))
            if not any(message in result.stdout + result.stderr for message in ("GOOGLE_MAPS_API_KEY is required", "Google OAuth credentials are required")):
                raise SystemExit(f"{tool['name']}: example did not reach the expected missing-key boundary")
    print(f"Verified reference for {len(tools)} tools and {sum(len(list(fields(t['inputSchema']))) for t in tools)} parameter paths; no Google calls")


if __name__ == "__main__":
    main()
